function showJourneys(tab='routes'){
 const real=tab==='routes';openDialog(`<p class="eyebrow">${t('journeys')}</p><h2>${t('routeTitle')}</h2><p>${real?t('routeIntro'):t('journeysIntro')}</p><div class="dialog-tabs"><button class="${real?'active':''}" data-action="route-library">${t('routesTab')} · ${routes.length}</button><button class="${!real?'active':''}" data-action="reading-library">${t('readingTab')} · ${journeys.length+courses.length}</button></div>${real?`<div class="route-grid">${routes.map(r=>`<button class="route-card" data-action="open-route" data-id="${r.id}">${routeMini(r)}<span class="eyebrow">${r.kind==='network'?t('network'):t('documentedJourney')}</span><strong>${esc(localized(r.title))}</strong><p>${esc(localized(r.summary||r.description)).slice(0,220)}${localized(r.summary||r.description).length>220?'…':''}</p><small>${formatPeriod(r,state.lang)} · ${r.stops.length} ${t('stops')} · ${t('open')}</small></button>`).join('')}</div>`:`<div class="journey-grid">${readingPaths().map((j,i)=>`<button class="journey-card" data-action="${j.questions?'open-course':'start-journey'}" data-id="${j.id}"><span class="number">${String(i+1).padStart(2,'0')}</span><strong>${esc(localized(j.title))}</strong><p>${esc(localized(j.description))}</p><small>${j.stops.length} ${t('records')} · ${j.estimatedMinutes?j.estimatedMinutes+(state.lang==='zh'?' 分钟 · ':' min · '):''}${t('begin')}</small></button>`).join('')}</div>`}`,{nav:'journeys-nav'});
}
function readingPaths(){return [...journeys,...courses.map(c=>({...c,description:c.summary,stops:c.recordIds}))];}
function showCourse(id,completed=false){
 const c=courses.find(x=>x.id===id);if(!c)return;
 openDialog(`<p class="eyebrow">${t('readSequence')} · ${c.estimatedMinutes} ${state.lang==='zh'?'分钟':'MIN'}</p><h2>${esc(localized(c.title))}</h2><p>${esc(localized(c.summary))}</p>${completed?`<p class="course-complete">✓ ${t('journeyDone')}</p>`:''}<div class="button-row"><button class="primary-button" data-action="start-journey" data-id="${c.id}">${completed?t('playAgain'):t('begin')}</button><button class="secondary-button" data-action="reading-library">${t('readingTab')}</button></div><h3>${state.lang==='zh'?'阅读路径':'Your reading path'}</h3><div class="course-records">${c.recordIds.map((id,i)=>{const r=byId(id);return `<button class="elsewhere-card" data-action="open-dialog-story" data-id="${id}"><span><small>${String(i+1).padStart(2,'0')} · ${regionName(r.region)}</small><strong>${esc(localized(r.title))}</strong><small>${formatPeriod(r,state.lang)}</small></span>↗</button>`;}).join('')}</div><h3>${state.lang==='zh'?'带着问题阅读':'Questions to carry with you'}</h3><ol class="course-questions">${c.questions.map(q=>`<li>${esc(localized(q))}</li>`).join('')}</ol><div class="course-activity"><h3>${state.lang==='zh'?'试一试':'Try this comparison'}</h3><p>${esc(localized(c.activity))}</p></div>${c.routeIds.length?`<h3>${state.lang==='zh'?'继续探索地图':'Continue on the map'}</h3><div class="button-row">${c.routeIds.map(id=>`<button class="secondary-button" data-action="open-route" data-id="${id}">${esc(localized(routes.find(r=>r.id===id).title))} ↗</button>`).join('')}</div>`:''}`,{nav:'journeys-nav'});
}
function startJourney(id){const chosen=readingPaths().find(j=>j.id===id);if(!chosen)return;closeDialog();clearPaths();clearSelection();challenge=null;journey=chosen;journeyIndex=0;state.region='all';state.theme='all';state.query='';state.savedOnly=false;kind='all';state.mode='year';visitJourneyStop();}
function visitJourneyStop(){const r=byId(journey.stops[journeyIndex]);if(!r)return;state.year=journey.year??representativeYear(r,snapshotData.snapshots);state.mode='year';selectStory(r.id,{keepPath:true});}
function openRoute(id){const chosen=routes.find(r=>r.id===id);if(!chosen)return;if($('#dialog').open)closeDialog();clearPaths();clearSelection();challenge=null;route=chosen;routeIndex=0;state.region='all';state.theme='all';state.query='';state.savedOnly=false;kind='all';state.mode='year';const s=routeStops(route)[0];state.year=validYear(s?.year)?s.year:chosen.start;render();resetMap();if(matchMedia('(max-width:700px)').matches)$('.map-stage').scrollIntoView({block:'start',behavior:reducedMotion?'instant':'smooth'});}
function routeDetail(r){const stops=routeStops(r),s=stops[routeIndex],caveat=[localized(r.dateNote),localized(r.caveat)].filter((note,i,all)=>note&&all.indexOf(note)===i).join(' ');return `<div class="detail-region">${r.kind==='network'?t('network'):t('documentedJourney')}</div><h2 tabindex="-1">${esc(localized(r.title))}</h2><p class="detail-period">${formatPeriod(r,state.lang)}</p><p class="detail-body">${esc(localized(r.summary||r.description))}</p><div class="detail-note"><strong>${t('routeEvidence')}</strong>${esc(caveat)} ${t('routeCaution')}</div><section class="detail-section"><h3>${stops.length} ${t('stops')}</h3><ol class="milestones">${stops.map((stop,i)=>`<li class="${i===routeIndex?'active':''}"><button data-action="route-stop" data-index="${i}"><time>${validYear(stop.year)?milestoneDate(stop):t('network')}</time><strong>${esc(localized(stop.label))}</strong><p>${esc(localized(stop.description))}</p></button></li>`).join('')}</ol></section><section class="detail-section"><h3>${t('readSources')}</h3><ol class="detail-sources">${(r.sources||[]).map(s=>`<li>${sourceLink(s)}</li>`).join('')}</ol></section>`;}
function revealActiveMilestone(){const panel=$('#detail'),item=$('#detail .milestones li.active');if(!item)return;const target=panel.scrollTop+item.getBoundingClientRect().top-panel.getBoundingClientRect().top-panel.clientHeight/2+item.clientHeight/2;panel.scrollTo({top:Math.max(0,target),behavior:reducedMotion?'instant':'smooth'});}
function visitRouteStop(index){if(!route)return;const stops=routeStops(route);routeIndex=Math.max(0,Math.min(stops.length-1,index));const s=stops[routeIndex];if(validYear(s.year))state.year=s.year;render();focusLocation(s,3);revealActiveMilestone();}
let endedPerson='';
function visitMilestone(id,index){const r=byId(id),m=r?.milestones?.[index];if(!m)return;endedPerson='';personIndex=index;state.entry=id;state.year=m.year;state.mode='year';render();focusLocation(m.location,3.3);revealActiveMilestone();}
function renderRoutes(){
 if(!routeLayer)return;routeLayer.raise();const person=selected?.milestones?.length?selected:null,stops=route?routeStops(route):person?personStops(person):[],r=route||{kind:'biography'},index=route?routeIndex:personIndex,k=transform.k||1;
 const lines=routeLines(r,stops);routeLayer.selectAll('path').data(lines).join('path').attr('class',l=>'route-path'+(stops[index]?.id===l.b.id?' active':'')).attr('d',l=>path({type:'LineString',coordinates:[[l.a.lon,l.a.lat],[l.b.lon,l.b.lat]]}));
 const nodes=routeLayer.selectAll('g.route-node').data(stops,s=>s.id).join(enter=>{const g=enter.append('g').attr('class','route-node').attr('role','button').attr('tabindex',0);g.append('circle');g.append('text').attr('class','route-number');g.append('text').attr('class','route-label');return g;});
 nodes.attr('transform',s=>{const p=projection([s.lon,s.lat]);return `translate(${p[0]},${p[1]}) scale(${1/k})`;}).classed('active',(_,i)=>i===index).attr('aria-label',(s,i)=>`${i+1}. ${localized(s.label)}${validYear(s.year)?', '+formatYear(s.year,state.lang):''}`).on('click',(event,s)=>{event.stopPropagation();const i=stops.indexOf(s);if(route)visitRouteStop(i);else visitMilestone(person.id,i);}).on('keydown',(event,s)=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();const i=stops.indexOf(s);if(route)visitRouteStop(i);else visitMilestone(person.id,i);}});
 nodes.filter((s,i)=>i===index).raise();
 nodes.select('circle').attr('r',(_,i)=>i===index?10:8);nodes.select('.route-number').text((_,i)=>r.kind==='network'?'·':i+1);nodes.select('.route-label').attr('x',13).attr('y',4).text((s,i)=>layers.labels&&(k>1.7||i===index)&&(!stops.some((o,j)=>j!==i&&o.lat===s.lat&&o.lon===s.lon)||i===index)?localized(s.label).slice(0,26):'');
}
function renderJourney(){
 const el=$('#journey-strip'),person=selected?.milestones?.length&&selected.id!==endedPerson?selected:null,active=journey||route||person;el.hidden=!active;$('.map-stage').classList.toggle('has-journey',!!active);if(!active)return;
 const index=journey?journeyIndex:route?routeIndex:personIndex,length=journey?journey.stops.length:route?route.stops.length:person.milestones.length;
 el.innerHTML=`<p class="eyebrow">${journey?t('readSequence'):route?(route.kind==='network'?t('network'):t('documentedJourney')):t('biography')}</p><h3>${esc(localized(active.title))}</h3><div class="route-dots">${Array.from({length},(_,i)=>`<button data-action="path-stop" data-index="${i}" class="${i===index?'active':''}" aria-label="${state.lang==='zh'?'节点':'Stop'} ${i+1}"></button>`).join('')}</div><div class="journey-controls">${journey?.questions?`<button data-action="open-course" data-id="${journey.id}" class="reading-guide-link">${state.lang==='zh'?'阅读指南':'Study guide'}</button>`:''}<button data-action="journey-prev" ${index===0?'disabled':''}>‹ ${t('previous')}</button><span>${index+1} / ${length}</span><button data-action="journey-next">${index===length-1?t('finish'):t('next')+' ›'}</button><button data-action="journey-stop" aria-label="${t('stop')}">×</button></div>`;
}
function advanceJourney(delta){if(journey){const next=journeyIndex+delta;if(next>=journey.stops.length){const finished=journey;journey=null;render();if(finished.questions)showCourse(finished.id,true);else toast(t('journeyDone'));return;}journeyIndex=Math.max(0,next);visitJourneyStop();}else if(route){const next=routeIndex+delta;if(next>=route.stops.length){route=null;render();toast(t('journeyDone'));return;}visitRouteStop(Math.max(0,next));}else if(selected?.milestones?.length){const next=personIndex+delta;if(next>=selected.milestones.length){endedPerson=selected.id;renderJourney();toast(t('journeyDone'));return;}visitMilestone(selected.id,Math.max(0,next));}}
function showPeople(){openDialog(`<p class="eyebrow">${t('people')}</p><h2>${t('peopleTitle')}</h2><p>${t('peopleIntro')}</p><div class="people-grid">${[...people].sort((a,b)=>a.start-b.start).map(r=>`<button class="person-card" style="--region-color:${colorFor(r)}" data-action="open-dialog-story" data-id="${r.id}"><span class="person-monogram">${esc(state.lang==='zh'?localized(r.name||r.title).slice(0,1):localized(r.name||r.title).split(' ').map(w=>w[0]).slice(0,2).join(''))}</span><strong>${esc(localized(r.name||r.title))}</strong><small>${formatPeriod(r,state.lang)}<br>${t('focusPeriod')} · ${esc(regionName(r.region))}</small><p>${r.milestones.length} ${t('life')} · ${t('open')}</p></button>`).join('')}</div>`,{nav:'people-nav'});}
function showChronology(){
 const w=chronologySpan==='all'?{start:MIN_YEAR,end:MAX_YEAR}:timeWindow(state.year,chronologySpan||undefined),a=toOrdinal(w.start),b=toOrdinal(w.end),pos=(toOrdinal(state.year)-a)/(b-a)*100;
 const ticks=Array.from({length:6},(_,i)=>fromOrdinal(Math.round(a+(b-a)*i/5))),filtered=records.filter(r=>state.region==='all'||r.region===state.region);
 const rows=REGIONS.filter(r=>state.region==='all'||r===state.region).map(id=>{const list=filtered.filter(r=>r.region===id),lanes=timelineLanes(list,w,10);return `<section class="chronology-region"><div class="chronology-region-label"><strong style="color:${REGIONAL[id].color}">${esc(regionName(id))}</strong><small>${lanes.rows.length} ${t('records')}${lanes.omitted?`<br>+ ${lanes.omitted} ${t('notShown')}`:''}</small></div><div class="chronology-tracks" style="height:${lanes.count*30}px;--region-color:${REGIONAL[id].color}"><div class="chronology-now" style="left:${pos}%"></div>${lanes.rows.map(({record:r,left,width,lane})=>`<button class="chronology-bar ${activeAt(r,state.year)?'active':''}" data-action="open-dialog-story" data-id="${r.id}" style="left:${left}%;width:${width}%;top:${lane*30}px" title="${esc(localized(r.title))} · ${formatPeriod(r,state.lang)}" aria-label="${esc(localized(r.title))}, ${formatPeriod(r,state.lang)}">${esc(shortTitle(r))}</button>`).join('')}</div></section>`;}).join('');
 openDialog(`<p class="eyebrow">${formatYear(state.year,state.lang)} · ${t('chronology')}</p><h2>${t('chronologyTitle')}</h2><p>${t('chronologyIntro')}</p><div class="chronology-toolbar"><button data-action="chronology-shift" data-direction="-1">← ${t('previous')}</button><label for="chronology-window" class="sr-only">${t('chronologyWindow')}</label><select id="chronology-window"><option value="0" ${chronologySpan===0?'selected':''}>${state.lang==='zh'?'当前时期':'This period'}</option>${[300,600,1200,3000].map(n=>`<option value="${n}" ${chronologySpan===n?'selected':''}>${n} ${t('years')}</option>`).join('')}<option value="all" ${chronologySpan==='all'?'selected':''}>${t('wholeTimeline')}</option></select><button data-action="chronology-shift" data-direction="1">${t('next')} →</button></div><div class="chronology-viewport"><div class="chronology-scale">${ticks.map(y=>`<span>${formatYear(y,state.lang)}</span>`).join('')}</div>${rows}</div><p class="chronology-footnote">${t('chronologyNote')}</p>`,{wide:true,nav:'chronology-nav'});
 $('#chronology-window').addEventListener('change',e=>{chronologySpan=e.target.value==='all'?'all':Number(e.target.value);showChronology();});
}
function shiftChronology(direction){const w=timeWindow(state.year,typeof chronologySpan==='number'?chronologySpan||undefined:3000),n=Math.round((toOrdinal(w.end)-toOrdinal(w.start))/2);state.year=fromOrdinal(Math.max(toOrdinal(MIN_YEAR),Math.min(toOrdinal(MAX_YEAR),toOrdinal(state.year)+direction*n)));clearSelection();render();showChronology();}
function showChallengeIntro(){openDialog(`<p class="eyebrow">${t('challenge')}</p><h2>${t('challengeTitle')}</h2><p>${t('challengeIntro')}</p><p>${t('challengeApprox')}</p><div class="button-row"><button class="primary-button" data-action="challenge-start">${t('startChallenge')}</button></div>`,{nav:'challenge-nav'});}
function startChallenge(){if($('#dialog').open)closeDialog();clearPaths();clearSelection();state.query='';state.region='all';state.theme='all';kind='all';const pool=['angkor','great-zimbabwe','cahokia','mohenjo-daro','teotihuacan','persepolis','caral','nan-madol','timbuktu','gobekli-tepe','quanzhou','rome-imperial-city'].map(byId).filter(Boolean);for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}challenge={entries:pool.slice(0,5),index:0,results:[],answered:false,finished:false};state.year=midpoint(challenge.entries[0]);render();resetMap();$('.map-stage').scrollIntoView({block:'start',behavior:'smooth'});}
function renderChallenge(){const panel=$('#challenge-panel');panel.hidden=!challenge;$('.map-stage').classList.toggle('challenge-mode',!!challenge);if(!challenge){renderQuizMap();return;}const c=challenge,r=c.entries[c.index],points=c.results.reduce((sum,x)=>sum+x.score,0);let body='';if(c.finished){body=`<h2>${t('challengeComplete')}</h2><div class="challenge-score">${points.toLocaleString()} / ${c.entries.length*1000}</div><p>${t('challengeApprox')}</p>${c.results.map(x=>`<button class="elsewhere-card" data-action="quiz-study" data-id="${x.id}"><span><strong>${esc(shortTitle(byId(x.id)))}</strong><small>${Math.round(x.km).toLocaleString()} km · ${x.score} / 1000</small></span>↗</button>`).join('')}<div class="button-row"><button class="primary-button" data-action="challenge-start">${t('playAgain')}</button></div>`;}else{const result=c.results[c.index];body=`<p class="challenge-progress">${t('round')} ${c.index+1} / ${c.entries.length} · ${t('score')} ${points}</p><h2>${esc(shortTitle(r))}</h2><p>${formatPeriod(r,state.lang)} · ${esc(regionName(r.region))}</p>${c.answered?`<div class="challenge-score">${result.score} / 1000</div><p>${Math.round(result.km).toLocaleString()} km ${t('distance')}</p><p>${esc(localized(r.summary).split(/[。.!?]/)[0])}.</p><a class="text-button" href="${esc(r.sources[0].url)}" target="_blank" rel="noopener noreferrer">${t('viewSource')}</a><div class="button-row"><button class="primary-button" data-action="quiz-next">${c.index===c.entries.length-1?t('finishChallenge'):t('nextRound')}</button></div>`:`<p>${t('challengeHint')}</p><details><summary>${t('keyboardGuess')}</summary><form id="guess-form"><label>${t('latitude')}<input name="lat" type="number" step="any" min="-90" max="90" required aria-label="${t('latitude')}"></label><label>${t('longitude')}<input name="lon" type="number" step="any" min="-180" max="180" required aria-label="${t('longitude')}"></label><button type="submit">${t('submitGuess')}</button></form></details>`}`;}panel.innerHTML=`<button class="detail-close" data-action="quiz-close" aria-label="${t('close')}">×</button>`+body;$('#guess-form')?.addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget),lat=Number(data.get('lat')),lon=Number(data.get('lon'));if(Number.isFinite(lat)&&Number.isFinite(lon)&&Math.abs(lat)<=90&&Math.abs(lon)<=180)guessPlace({lat,lon});});renderQuizMap();}
function guessPlace(guess){if(!challenge||challenge.answered||challenge.finished)return;const r=challenge.entries[challenge.index],km=greatCircleKm(guess,r.location);challenge.results.push({id:r.id,km,score:quizScore(km),guess,target:r.location});challenge.answered=true;renderChallenge();}
function nextQuiz(){if(!challenge)return;if(challenge.index===challenge.entries.length-1){challenge.finished=true;renderChallenge();return;}challenge.index++;challenge.answered=false;state.year=midpoint(challenge.entries[challenge.index]);render();resetMap();}
function renderQuizMap(){if(!quizLayer)return;const result=challenge?.answered&&!challenge.finished?challenge.results[challenge.index]:null,k=transform.k||1;quizLayer.selectAll('path').data(result?[result]:[]).join('path').attr('class','quiz-line').attr('d',d=>path({type:'LineString',coordinates:[[d.guess.lon,d.guess.lat],[d.target.lon,d.target.lat]]}));const points=result?[{...result.guess,type:'guess'},{...result.target,type:'target'}]:[];quizLayer.selectAll('circle').data(points).join('circle').attr('class',d=>'quiz-point '+d.type).attr('cx',d=>projection([d.lon,d.lat])[0]).attr('cy',d=>projection([d.lon,d.lat])[1]).attr('r',6/k).attr('stroke-width',2/k);quizLayer.selectAll('text').data(points).join('text').attr('class','marker-label').attr('x',d=>projection([d.lon,d.lat])[0]+10/k).attr('y',d=>projection([d.lon,d.lat])[1]+4/k).attr('font-size',11/k).attr('stroke-width',3/k).text(d=>d.type==='guess'?t('yourGuess'):t('target'));}

function showCompare(){
  const choices=state.compare.map(byId).filter(Boolean);
  let overlap='';
  if(choices.length===2){const start=Math.max(...choices.map(r=>r.start)),end=Math.min(...choices.map(r=>r.end));overlap=`<p class="comparison-note">${start<=end?`${t('compareAt')}: ${esc(formatPeriod({start,end},state.lang))}.`:t('compareNotAt')+'.'} ${t('compareCaution')}</p>`;}
  openDialog(`<h2>${t('compareTitle')}</h2><p>${t('compareIntro')}</p>${overlap}<div class="compare-grid">${choices.map(r=>`<section class="compare-column"><p class="eyebrow">${esc(regionName(r.region))}</p><h3>${esc(localized(r.title))}</h3><p class="comparison-year">${esc(formatPeriod(r,state.lang))}</p><p>${esc(localized(r.summary))}</p><p><strong>${t('dateContext')}</strong><br>${esc(localized(r.dateNote))}</p><ol class="detail-sources">${r.sources.map(s=>`<li>${sourceLink(s)}</li>`).join('')}</ol><button class="text-button" data-action="compare-remove-dialog" data-id="${r.id}">${t('removeCompareAction')}</button></section>`).join('')}${choices.length<2?`<section class="compare-column"><p>${t('compareEmpty')}</p><button class="primary-button" data-action="close-dialog">${t('explore')}</button></section>`:''}</div>`);
}
function showNotebook(){
  setActiveNav('notebook-nav');
  const ids=[...new Set([...notebook.saved,...Object.keys(notebook.notes).filter(k=>notebook.notes[k].trim())])];
  const entries=ids.map(byId).filter(Boolean);
  openDialog(`<h2>${t('notebook')}</h2><p>${t('notebookIntro')}</p><div class="button-row"><button class="primary-button" data-action="export-notebook">${t('export')}</button><button class="secondary-button" data-action="saved-filter">${t('savedFilter')}</button></div><div class="notebook-list">${entries.length?entries.map(r=>`<div class="notebook-row"><div><strong>${esc(localized(r.title))}</strong><small>${esc(formatPeriod(r,state.lang))}</small>${notebook.notes[r.id]?`<p>${esc(notebook.notes[r.id])}</p>`:''}</div><button class="secondary-button" data-action="open-dialog-story" data-id="${r.id}">${t('openStory')}</button></div>`).join(''):`<p>${t('emptyNotebook')}</p>`}</div><label class="import-label">${t('import')}<input id="notebook-import" type="file" accept=".json,application/json"></label><p>${t('importHint')}</p>`);
  $('#notebook-import').addEventListener('change',async event=>{
    const file=event.target.files[0];if(!file)return;
    try{if(file.size>1024*1024)throw new Error(state.lang==='en'?'The notebook exceeds 1 MB.':'笔记本超过1 MB。');const incoming=validateNotebook(JSON.parse(await file.text()),records);notebook=mergeNotebooks(notebook,incoming);persist();render();showNotebook();toast(storageOK?t('importSuccess'):t('noteFailed'));}
    catch(error){toast((state.lang==='en'?'Import failed: ':'导入失败：')+error.message);event.target.value='';}
  });
}
function downloadJSON(name,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportNotebook(){downloadJSON('world-history-notebook.json',notebook);}

function showAbout(){
 const sourceCount=new Set([...records,...routes,...territories.features.map(f=>f.properties)].flatMap(r=>r.sources.map(s=>{const u=new URL(s.url);u.hash='';return u.href;}))).size;
 openDialog(`<p class="eyebrow">WORLD HISTORY ATLAS · 寰宇时序</p><h2>${t('aboutTitle')}</h2><p>${t('aboutIntro')}</p><div class="source-counts"><div><strong>${records.length}</strong><span>${t('records')}</span></div><div><strong>${people.length}</strong><span>${t('people')}</span></div><div><strong>${snapshotData.snapshots.length}</strong><span>${t('snapshot')}</span></div><div><strong>${sourceCount}</strong><span>${state.lang==='zh'?'引文页面':'cited pages'}</span></div></div><h3>${t('method')}</h3><p>${t('mapMethod')}</p><p>${t('timeMethod')}</p><h3>${t('bordersHeading')}</h3><p>${t('bordersMethod')}</p><p>${t('routeIntro')}</p><h3>${t('scopeHeading')}</h3><p>${t('scopeMethod')}</p><table class="coverage-table"><thead><tr><th>${t('region')}</th><th>${t('records')}</th></tr></thead><tbody>${REGIONS.map(id=>`<tr><td>${regionName(id)}</td><td>${records.filter(r=>r.region===id).length}</td></tr>`).join('')}</tbody></table><h3>${t('privacyHeading')}</h3><p>${t('privacyMethod')}</p><p>${t('keyboard')}</p><h3>${t('credits')}</h3><ul><li><a href="https://github.com/haitaowu12/jiangshan-map" target="_blank" rel="noopener noreferrer">Jiangshan Map / 江山时序 ↗</a> · ${state.lang==='zh'?'交互灵感与三幅注明出处的示意轮廓':'Interaction inspiration and three attributed schematic outlines'}</li><li><a href="https://github.com/aourednik/historical-basemaps" target="_blank" rel="noopener noreferrer">Historical Basemaps ↗</a> · ${state.lang==='zh'?'精选近似疆域':'Selected approximate territory geometry'} · GPL-3.0</li><li><a href="https://awmc.unc.edu/gis-data/" target="_blank" rel="noopener noreferrer">Ancient World Mapping Center ↗</a> · Rome, 200 CE · ODbL-1.0</li><li><a href="https://www.naturalearthdata.com/about/terms-of-use/" target="_blank" rel="noopener noreferrer">Natural Earth ↗</a> · ${state.lang==='zh'?'地理参照，公有领域':'Physical and modern reference geometry, public domain'}</li><li><a href="https://d3js.org/" target="_blank" rel="noopener noreferrer">D3 7.9.0 ↗</a> · Equal Earth</li></ul><p>${t('copyright')}</p><div class="button-row"><a class="secondary-button" href="./data/history.json" download="world-history-data.json">${t('downloadData')}</a><a class="secondary-button" href="./data/people.json" download="world-history-people.json">${t('people')} JSON</a><a class="secondary-button" href="./data/routes.json" download="world-history-routes.json">${t('journeys')} JSON</a><a class="secondary-button" href="./data/map-snapshots.json" download="world-history-map-snapshots.json">${t('snapshot')} JSON</a></div><h3>${t('sourceCatalog')}</h3><p>${t('sourceChecked')}</p>${records.map(r=>`<details class="source-catalog"><summary>${esc(localized(r.title))} · ${esc(formatPeriod(r,state.lang))}</summary><p>${esc(localized(r.dateNote))}</p><ul>${r.sources.map(s=>`<li>${sourceLink(s)}</li>`).join('')}</ul></details>`).join('')}`);
}
async function shareView(){updateURL();const url=location.href;try{await navigator.clipboard.writeText(url);toast(t('shareCopied'));}catch{openDialog(`<h2>${t('shareTitle')}</h2><p>${t('shareDescription')}</p><input class="clipboard-field" id="share-url" aria-label="View URL" readonly value="${esc(url)}">`);$('#share-url').select();}}
function filterChanged(){stopPlayback();clearPaths();territorySelection=null;placeSelection=null;if(state.entry&&!filterRecords(records,state,notebook.saved).some(r=>r.id===state.entry))state.entry='';if(state.entry&&kind!=='all'&&inferKind(byId(state.entry))!==kind)state.entry='';render();}
function wireEvents(){
 $('#search').addEventListener('input',event=>{state.query=event.target.value;if(state.query)state.mode='all';filterChanged();});
 $('#region').addEventListener('change',event=>{state.region=event.target.value;filterChanged();if(state.region==='all')resetMap();else focusRegion(state.region);});$('#theme').addEventListener('change',event=>{state.theme=event.target.value;filterChanged();});
 $('#mode-year').addEventListener('click',()=>{state.mode='year';filterChanged();});$('#mode-all').addEventListener('click',()=>{state.mode='all';filterChanged();});$('#reset-filters').addEventListener('click',resetFilters);
 $('#timeline-slider').addEventListener('input',event=>setYear(yearFromSlider(event.target.value)));
 $('#year-form').addEventListener('submit',event=>{event.preventDefault();const raw=$('#year-input').value.trim(),magnitude=Number(raw),year=$('#era').value==='bce'?-magnitude:magnitude;if(!/^\d+$/.test(raw)||magnitude<=0||!validYear(year)){toast(t('invalidYear'));return;}setYear(year);});$('#era').addEventListener('change',()=>$('#year-input').max=$('#era').value==='ce'?String(MAX_YEAR):String(-MIN_YEAR));
 $('#play').addEventListener('click',playTimeline);$('#previous-time').addEventListener('click',()=>stepTime(-1));$('#next-time').addEventListener('click',()=>stepTime(1));
 $('#language').addEventListener('click',()=>{stopPlayback();state.lang=state.lang==='en'?'zh':'en';applyLanguage();render();});
 $('#zoom-in').addEventListener('click',()=>zoomBy(1.5));$('#zoom-out').addEventListener('click',()=>zoomBy(1/1.5));$('#zoom-reset').addEventListener('click',resetMap);$('#world-reset').addEventListener('click',()=>{resetMap();state.region='all';render();});
 $('#layer-menu-button').addEventListener('click',()=>{const open=$('#layer-menu').hidden;$('#layer-menu').hidden=!open;$('#layer-menu-button').setAttribute('aria-expanded',String(open));});
 $('#explore-nav').addEventListener('click',()=>{if($('#dialog').open)closeDialog();challenge=null;render();$('.map-stage').scrollIntoView({block:'start',behavior:'smooth'});});$('#chronology-nav').addEventListener('click',showChronology);$('#chronology-open').addEventListener('click',showChronology);$('#journeys-nav').addEventListener('click',()=>showJourneys());$('#people-nav').addEventListener('click',showPeople);$('#challenge-nav').addEventListener('click',showChallengeIntro);$('#notebook-nav').addEventListener('click',showNotebook);$('#about-nav').addEventListener('click',showAbout);$('#map-method').addEventListener('click',showAbout);$('#compare-button').addEventListener('click',showCompare);$('#share').addEventListener('click',shareView);
 $('#brand-home').addEventListener('click',event=>{event.preventDefault();stopPlayback();clearPaths();clearSelection();challenge=null;kind='all';state={...defaultState(),lang:state.lang};applyLanguage();render();resetMap();});$('.skip').addEventListener('click',event=>{event.preventDefault();$('#stories').focus();$('#stories').scrollIntoView({block:'start',behavior:'instant'});});
 $('#dialog').addEventListener('close',()=>setActiveNav('explore-nav'));$('#dialog').addEventListener('click',event=>{if(event.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog();}});
 document.addEventListener('change',event=>{const key=event.target.dataset.layer;if(key&&Object.hasOwn(layers,key)){layers[key]=event.target.checked;try{localStorage.setItem('world-history-atlas-layers-v2',JSON.stringify(layers));}catch{}render();}});
 document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button)return;const id=button.dataset.id,index=Number(button.dataset.index);switch(button.dataset.action){
 case 'select':endedPerson='';selectStory(id);break;
 case 'open-dialog-story':closeDialog();clearPaths();state.region='all';state.theme='all';state.query='';state.savedOnly=false;kind='all';endedPerson='';selectStory(id);break;
 case 'close-detail':{const old=state.entry;clearSelection();clearPaths();render();$(`#stories [data-id="${old}"]`)?.focus({preventScroll:true});break;}
 case 'close-dialog':closeDialog();break;
 case 'browse-all':state.mode='all';resetFilters();break;
 case 'kind':kind=id;filterChanged();break;
 case 'year':setYear(Number(button.dataset.year));resetMap();break;
 case 'event-year':{const r=byId(id);if(r){state.year=r.start;state.mode='year';selectStory(id);}break;}
 case 'jump-period':state.mode='year';setYear(midpoint(byId(id)));selectStory(id);break;
 case 'save':toggleSave(id);break;
 case 'compare-add':toggleCompare(id);break;
 case 'compare-remove-dialog':state.compare=state.compare.filter(x=>x!==id);render();showCompare();break;
 case 'start-journey':startJourney(id);break;
 case 'open-course':showCourse(id);break;
 case 'journey-prev':advanceJourney(-1);break;
 case 'journey-next':advanceJourney(1);break;
 case 'journey-stop':if(selected?.milestones)endedPerson=selected.id;clearPaths();render();break;
 case 'path-stop':if(journey){journeyIndex=index;visitJourneyStop();}else if(route)visitRouteStop(index);else if(selected?.milestones)visitMilestone(selected.id,index);break;
 case 'route-library':showJourneys('routes');break;
 case 'reading-library':showJourneys('reading');break;
 case 'open-route':openRoute(id);break;
 case 'route-stop':visitRouteStop(index);break;
 case 'milestone':visitMilestone(id,index);break;
 case 'legend-toggle':$('#territory-legend').classList.toggle('legend-expanded');break;
 case 'territory-story':state.year=Number(button.dataset.year);state.mode='year';selectStory(id);break;
 case 'territory':{const f=territories.features.find(f=>f.properties.id===id);if(f)selectTerritory(f);break;}
 case 'trace':{const r=byId(id);if(r){stopPlayback();clearPaths();clearSelection();placeSelection=r.location;render();}break;}
 case 'chronology-shift':shiftChronology(Number(button.dataset.direction));break;
 case 'challenge-start':startChallenge();break;
 case 'quiz-next':nextQuiz();break;
 case 'quiz-close':challenge=null;render();break;
 case 'quiz-study':challenge=null;selectStory(id);break;
 case 'about':showAbout();break;
 case 'export-notebook':exportNotebook();break;
 case 'saved-filter':closeDialog();state.savedOnly=true;state.mode='all';state.region='all';state.theme='all';state.query='';kind='all';clearSelection();clearPaths();render();resetMap();break;
 }});
 document.addEventListener('input',event=>{if(event.target.id==='story-note'){notebook.notes[event.target.dataset.id]=event.target.value;persist();$('#note-state').textContent=storageOK?t('noteSaved'):t('noteFailed');}});
 document.addEventListener('keydown',event=>{const editing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);if(event.key==='Escape'&&!$('#dialog').open){if(!$('#layer-menu').hidden){$('#layer-menu').hidden=true;$('#layer-menu-button').setAttribute('aria-expanded','false');return;}challenge=null;clearSelection();clearPaths();render();}if(event.key==='/'&&!$('#dialog').open&&!editing){event.preventDefault();$('#search').focus();$('#search').scrollIntoView({block:'center',behavior:'smooth'});}if(event.code==='Space'&&!editing&&!$('#dialog').open&&event.target===document.body){event.preventDefault();playTimeline();}});
 window.addEventListener('hashchange',()=>{stopPlayback();clearPaths();clearSelection();challenge=null;readURL();applyLanguage();render();focusCurrentSelection();});document.addEventListener('visibilitychange',()=>{if(document.hidden)stopPlayback();});
}
function resolvePlace(query,year){const q=String(query||'').normalize('NFKC').toLocaleLowerCase();if(!q)return [];return records.filter(r=>[r.id,r.title.en,r.title.zh,r.location.label,r.name?.en||'',r.name?.zh||''].some(v=>v.normalize('NFKC').toLocaleLowerCase().includes(q))).sort((a,b)=>(activeAt(b,year)?1:0)-(activeAt(a,year)?1:0)||a.start-b.start);}
function readURL(){endedPerson='';state=stateFromHash(location.hash,records);const extra=safeMapState(location.hash);kind=extra.kind;route=routes.find(r=>r.id===extra.route)||null;routeIndex=route?Math.min(extra.stop,route.stops.length-1):0;const p=new URLSearchParams(location.search);if(!location.hash&&p.size){state.year=normalizeYear(p.get('year'),state.year);state.lang=p.get('lang')==='zh'?'zh':'en';const r=byId(p.get('person'))||resolvePlace(p.get('person')||p.get('place'),state.year)[0];if(r)state.entry=r.id;}const hp=new URLSearchParams(location.hash.slice(1));journey=route?null:readingPaths().find(j=>j.id===hp.get('reading'))||null;if(journey){journeyIndex=Math.max(0,Math.min(journey.stops.length-1,Number.parseInt(hp.get('step')||'0',10)||0));state.entry=journey.stops[journeyIndex];state.mode='year';state.year=journey.year??(activeAt(byId(state.entry),state.year)?state.year:midpoint(byId(state.entry)));}const r=byId(state.entry);if(r?.milestones?.length)personIndex=r.milestones.reduce((best,m,i)=>yearDistance(m.year,state.year)<yearDistance(r.milestones[best].year,state.year)?i:best,0);}
function exposeAPI(){window.atlasAPI=Object.freeze({version:'0.2.0',resolvePlace:(place,year=state.year)=>resolvePlace(place,normalizeYear(year)).map(r=>({id:r.id,title:r.title,start:r.start,end:r.end,location:r.location,kind:inferKind(r)})),inspect:({year=state.year,place}={})=>{const y=normalizeYear(year),matches=resolvePlace(place,y);return {year:y,territorySnapshot:nearestSnapshot(snapshotData.snapshots,y)?.year||null,matches:matches.map(r=>({id:r.id,title:r.title,period:{start:r.start,end:r.end},location:r.location,sources:r.sources,active:activeAt(r,y)}))};},locate:({year=state.year,place,person}={})=>{const y=normalizeYear(year),r=byId(person)||resolvePlace(person||place,y)[0];if(!r)return {ok:false,reason:'No matching entry in the current collection.'};state.year=y;selectStory(r.id);return {ok:true,id:r.id,year:state.year,url:location.href};}});}
async function init(){try{
 const files=['./data/history.json','./data/people.json','./data/routes.json','./assets/land.geojson','./data/territories.geojson','./data/map-snapshots.json','./assets/countries.geojson','./assets/rivers.geojson','./data/courses.json','./data/territories-awmc.geojson','./data/territories-jiangshan.geojson'];const responses=await Promise.all(files.map(f=>fetch(f)));if(responses.some(r=>!r.ok))throw new Error('A local atlas file could not load.');let histories,awmcGeo,jiangshanGeo;[histories,people,routes,land,territories,snapshotData,countries,rivers,courses,awmcGeo,jiangshanGeo]=await Promise.all(responses.map(r=>r.json()));territories={type:'FeatureCollection',features:[...territories.features,...awmcGeo.features,...jiangshanGeo.features]};records=[...histories,...people];const errors=validateRecords(records);if(errors.length)throw new Error(errors.slice(0,3).join('; '));if(!window.d3||land.type!=='FeatureCollection')throw new Error('The map renderer or land geometry is unavailable.');
 readURL();try{const raw=localStorage.getItem('world-history-atlas-notebook-v1');if(raw)notebook=validateNotebook(JSON.parse(raw),records);const savedLayers=JSON.parse(localStorage.getItem('world-history-atlas-layers-v2')||'{}');for(const key of Object.keys(layers))if(typeof savedLayers[key]==='boolean')layers[key]=savedLayers[key];}catch{storageOK=false;}
 applyLanguage();initializeMap();wireEvents();render();exposeAPI();if(selected||route)focusCurrentSelection();
 }catch(error){console.error('Atlas initialization failed:',error);$('#stories').innerHTML=`<div class="fatal"><strong>${t('loadError')}</strong><p>${esc(error.message)}</p><button id="retry-load" class="secondary-button">Reload</button></div>`;$('#retry-load').addEventListener('click',()=>location.reload());$('#map-date').textContent=state.lang==='zh'?'加载失败':'Unable to load';document.querySelectorAll('.timeline button,.timeline input,.timeline select').forEach(el=>el.disabled=true);}}
init();
